-- PT116-S2-Q5
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch01$PT116-S2-Q5$batch01$ AND q.stimulus=$batch01$Shipping Coordinator: If we send your shipment by air express, it will arrive tomorrow morning. If we send your shipment via ground carrier, it will arrive either tomorrow or the next day. Ground carrier is less expensive than air express, so which do you prefer?Customer: If I don’t choose air express, then I will not receive my shipment tomorrow, so I clearly have no choice but to spend the extra money and have it sent via air express.$batch01$ AND q.prompt=$batch01$The customer's response can best be explained on the assumption that she has misinterpreted the shipping coordinator to mean which one of the following?$batch01$ AND q.correct_choice=$batch01$D$batch01$) THEN RAISE EXCEPTION 'Question changed: PT116-S2-Q5'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT116-S2-Q5$batch01$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT116-S2-Q5'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT116-S2-Q5$batch01$ AND c.letter=$batch01$A$batch01$ AND c.choice_text=$batch01$Ground carrier is as reliable a shipping method as air express.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT116-S2-Q5 A'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT116-S2-Q5$batch01$ AND c.letter=$batch01$B$batch01$ AND c.choice_text=$batch01$If the shipment is sent by air express, it will arrive tomorrow.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT116-S2-Q5 B'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT116-S2-Q5$batch01$ AND c.letter=$batch01$C$batch01$ AND c.choice_text=$batch01$Ground carrier is not more expensive than air express.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT116-S2-Q5 C'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT116-S2-Q5$batch01$ AND c.letter=$batch01$D$batch01$ AND c.choice_text=$batch01$Unless the shipment is sent by air express, it will not arrive tomorrow.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT116-S2-Q5 D'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT116-S2-Q5$batch01$ AND c.letter=$batch01$E$batch01$ AND c.choice_text=$batch01$The greater the shipping cost, the faster the shipment will arrive.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT116-S2-Q5 E'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanation_steps s JOIN lr_explanations e ON e.id=s.explanation_id JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT116-S2-Q5$batch01$ AND e.style IN ('single','standard')) <> 0 OR (SELECT COUNT(*) FROM lr_explanation_choice_notes n JOIN lr_explanations e ON e.id=n.explanation_id JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT116-S2-Q5$batch01$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation changed: PT116-S2-Q5'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch01$PT116-S2-Q5$batch01$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch01$Conclusion (customer)$batch01$, $batch01$She must pay for air express to receive the shipment tomorrow.$batch01$), (1, $batch01$Evidence she attributes to the coordinator$batch01$, $batch01$Without air express, it will *not* arrive tomorrow.$batch01$), (2, $batch01$Evaluate$batch01$, $batch01$The coordinator guaranteed tomorrow morning for air express. For ground carrier, the coordinator offered *tomorrow or the next day*. The customer turns "ground may take until the next day" into "ground cannot arrive tomorrow." A guarantee of tomorrow by one method does not mean that method is required for tomorrow delivery.$batch01$), (3, $batch01$Goal$batch01$, $batch01$Find the conditional the customer falsely hears: no air express means no tomorrow delivery.$batch01$)) v(position,label,body) WHERE q.qid=$batch01$PT116-S2-Q5$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch01$A$batch01$, $batch01$Reliability of ground shipping does not explain the customer's belief that it cannot arrive tomorrow.$batch01$), ($batch01$B$batch01$, $batch01$The coordinator did say air express would arrive tomorrow. That guarantee alone does not rule out ground carrier also arriving tomorrow.$batch01$), ($batch01$C$batch01$, $batch01$Ground carrier is less expensive. That fact explains why the question is a choice, but not why the customer thinks ground cannot meet tomorrow's deadline.$batch01$), ($batch01$D$batch01$, $batch01$"Unless air express, not tomorrow" means that air express is necessary for tomorrow delivery. That is exactly the customer's mistaken interpretation. The coordinator said ground might arrive tomorrow, so the supposed necessity is false.$batch01$), ($batch01$E$batch01$, $batch01$The customer need not believe every more expensive shipment is faster. Her mistake concerns the specific alternatives and the certainty of next-day arrival.$batch01$)) v(letter,body) WHERE q.qid=$batch01$PT116-S2-Q5$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id) ON CONFLICT DO NOTHING;
